{"results": [{"id": "hp_doc_b7aff9f0b0f9fce7ff80efafab116a2d3d04b54ab6256d69ef642c24a013db4a", "title": "Sweden men's national inline hockey team", "text": "The Swedish men's national inline hockey team is one of the most successful inline hockey teams in the world. With notable alumni like Henrik Lundqvist the Swedes have won five gold medals as members of the Top Division at the IIHF Inline Hockey World Championships.", "score": 43.9107}, {"id": "hp_doc_d421df28fbc7ecb5e02e7d2437ebd93a798028b571bcc12c860fa0246c701ffe", "title": "Germany women's national inline hockey team", "text": "Germany women's national inline hockey team is the national team for Germany. The team finished eighth at the 2011 Women's World Inline Hockey Championships. The team competed in the 2013 Women's World Inline Hockey Championships.", "score": 25.3991}, {"id": "hp_doc_88312f67ba8532a96485ea699e29d78e7abf9fab28bd18a3f8fe2b0f0939f240", "title": "Great Britain women's national inline hockey team", "text": "Great Britain women's national inline hockey team is the national team for Great Britain. The team finished sixth at the 2011 Women's World Inline Hockey Championships. The team competed in the 2013 Women's World Inline Hockey Championships.", "score": 25.2052}], "remaining_searches": 2}
